package com.tecsup.controller; import com.tecsup.model.Producto; import com.tecsup.repository.ProductoRepository; import com.tecsup.dto.ProductoRequest; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; import org.springframework.web.bind.annotation.ExceptionHandler; @RestController @RequestMapping("/api/productos") public class ProductoController { private final ProductoRepository repo; public ProductoController(ProductoRepository r){repo=r;} @GetMapping public List<Producto> all(){return repo.findAll();} @GetMapping("/{id}") public Producto one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Producto no encontrado: "+id));} @PostMapping public ResponseEntity<Producto> create(@Valid @RequestBody ProductoRequest r){Producto e=new Producto(); e.setNombre(r.nombre()); e.setPrecio(r.precio()); e.setStock(r.stock()); e.setCategoriaId(r.categoriaId()); return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(e));} @PutMapping("/{id}") public Producto update(@PathVariable Long id,@Valid @RequestBody ProductoRequest r){Producto e=one(id); e.setNombre(r.nombre()); e.setPrecio(r.precio()); e.setStock(r.stock()); e.setCategoriaId(r.categoriaId()); return repo.save(e);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){repo.delete(one(id));return ResponseEntity.noContent().build();} }

@RestControllerAdvice class ApiErrors { @ExceptionHandler(NoSuchElementException.class) org.springframework.http.ResponseEntity<?> missing(Exception e){return org.springframework.http.ResponseEntity.status(404).body(java.util.Map.of("error",e.getMessage()));} @ExceptionHandler({org.springframework.web.bind.MethodArgumentNotValidException.class,IllegalArgumentException.class}) org.springframework.http.ResponseEntity<?> bad(Exception e){return org.springframework.http.ResponseEntity.badRequest().body(java.util.Map.of("error",e.getMessage()));} }
